package com.tutorhub.catalog.service;
import com.tutorhub.catalog.dto.*; import com.tutorhub.catalog.repository.*; import java.util.List; import org.springframework.stereotype.Service;
@Service public class CatalogService { private final SubjectRepository subjects; private final DistrictRepository districts; public CatalogService(SubjectRepository subjects,DistrictRepository districts){this.subjects=subjects;this.districts=districts;} public List<SubjectResponse> subjects(){return subjects.findByActiveTrueOrderByName().stream().map(x->new SubjectResponse(x.getId(),x.getName(),x.getSlug())).toList();} public List<DistrictResponse> districts(String city){return (city==null||city.isBlank()?districts.findAllByOrderByCityAscNameAsc():districts.findByCityIgnoreCaseOrderByName(city)).stream().map(x->new DistrictResponse(x.getId(),x.getCity(),x.getName())).toList();} }
